def hex_key(num):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    count = 0
    hex_primes = {"2", "3", "5", "7", "B", "D"}
    for digit in num:
        if digit in hex_primes and is_prime(int(digit, 16) if digit.isdigit() else int(digit, 16)):
            count += 1
    return count
